#!/usr/bin/env bash
#*****************************************************************************
# check_pins.sh — contract lint for the TestTop_L2ZhuJiang DUT.
#
# Extracts the emitted top-level port list (name + width) from
# build/zhujiang/TestTop_L2ZhuJiang.sv and diffs it against
# test/scripts/zhujiang/expected_pins.txt — the cohestra_v3 contract boundary:
#   clock/reset/log_* + per-L2 cchi_t1p{P}_* + per-L2 mon_chi_rn{P}_*
#   + axi_m0_*  (id 24b / addr 48b / data 256b)
# expected_pins.txt is generated by test/scripts/zhujiang/gen_expected_pins.sh from
# the proven TestTop_L2Avocado pin set (CCHI/monitor/clock/reset/log) and the
# AVOCADO_AXI_M_PORT_DECL macro of CHIron's avocado_dut_if.svh.
#
# Fails on any missing or width-mismatched contract pin; extra DUT pins are
# reported but non-fatal (the harness binds by name and ignores the rest).
#
# usage: check_pins.sh [path-to-TestTop_L2ZhuJiang.sv]
#*****************************************************************************
set -euo pipefail

XSCACHE_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)
TOP_SV=${1:-$XSCACHE_ROOT/build/zhujiang/TestTop_L2ZhuJiang.sv}
EXPECTED="$(dirname "${BASH_SOURCE[0]}")/expected_pins.txt"

[ -f "$TOP_SV" ]    || { echo "check_pins: DUT top not found: $TOP_SV"; exit 1; }
[ -f "$EXPECTED" ]  || { echo "check_pins: expected pin list not found: $EXPECTED (run gen_expected_pins.sh)"; exit 1; }

extract() {
    # normalize firtool SV port lines: "<name> <width>" (width = bit count).
    # firtool prints the direction keyword only when it changes, so scan the
    # whole module header region and take every name before a comma.
    awk '
        /^module[[:space:]]/ { inh = 1; next }
        inh && /^\);/        { inh = 0 }
        inh {
            line = $0
            sub(/\/\/.*$/, "", line)
            if (line !~ /[A-Za-z0-9_][[:space:]]*,?[[:space:]]*$/) next
            w = 1
            if (match(line, /\[[0-9]+:[0-9]+\]/)) {
                s = substr(line, RSTART + 1, RLENGTH - 2)
                split(s, m, ":")
                w = m[1] - m[2] + 1
            }
            match(line, /[A-Za-z_][A-Za-z0-9_]*[[:space:]]*,?[[:space:]]*$/)
            name = substr(line, RSTART, RLENGTH)
            gsub(/[[:space:],]/, "", name)
            print name, w
        }' "$1" | sort
}

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT

extract "$TOP_SV" > "$work/actual.txt"

missing=0
while read -r name width; do
    line=$(grep -E "^${name} " "$work/actual.txt" || true)
    if [ -z "$line" ]; then
        echo "check_pins: MISSING pin $name (expected width $width)"
        missing=1
    elif [ "$(echo "$line" | awk '{print $2}')" != "$width" ]; then
        echo "check_pins: WIDTH MISMATCH pin $name: expected $width, got $(echo "$line" | awk '{print $2}')"
        missing=1
    fi
done < "$EXPECTED"

[ "$missing" = 0 ] || { echo "check_pins: FAILED against $EXPECTED"; exit 1; }

extra=$(comm -13 <(awk '{print $1}' "$EXPECTED" | sort) <(awk '{print $1}' "$work/actual.txt") | wc -l)
echo "check_pins: OK — $(wc -l < "$EXPECTED") contract pins present and width-clean ($extra extra non-contract pins ignored)"
